create extension if not exists pgcrypto;
create table organisation(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,created_at timestamptz not null default now());
create table worker(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,external_key text not null,display_name text not null,email text,employment_type text not null check(employment_type in('employee','contractor','vendor')),department text,location text,cost_centre text,manager_external_key text,sponsor_external_key text,starts_on date not null,ends_on date,valid_from timestamptz not null default now(),valid_to timestamptz,unique(organisation_id,external_key,valid_from));
create table lifecycle_event(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,worker_id uuid not null references worker(id),event_type text not null check(event_type in('hire','move','leave','return','extend')),source_event_id text not null,effective_at timestamptz not null,received_at timestamptz not null default now(),state text not null default 'received' check(state in('received','validated','planned','running','completed','failed','cancelled')),payload jsonb not null default '{}'::jsonb,unique(organisation_id,source_event_id));
create index lifecycle_event_worker_order_idx on lifecycle_event(worker_id,effective_at,received_at);
create table birthright_rule(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,name text not null,version integer not null,condition jsonb not null,access_packages text[] not null default '{}',state text not null check(state in('draft','approved','active','retired')),effective_from timestamptz,created_at timestamptz not null default now(),unique(organisation_id,name,version));
create table provisioning_target(id uuid primary key default gen_random_uuid(),organisation_id uuid not null references organisation(id) on delete cascade,name text not null,connector_type text not null,rate_limit_per_minute integer not null check(rate_limit_per_minute>0),active boolean not null default true,unique(organisation_id,name));
create table provisioning_task(id uuid primary key default gen_random_uuid(),event_id uuid not null references lifecycle_event(id) on delete cascade,target_id uuid not null references provisioning_target(id),operation text not null check(operation in('create','update','disable','delete','grant','revoke')),state text not null default 'queued' check(state in('queued','running','waiting','succeeded','failed','cancelled')),idempotency_key text not null unique,attempts integer not null default 0,receipt jsonb,created_at timestamptz not null default now(),completed_at timestamptz);
create table reconciliation_run(id uuid primary key default gen_random_uuid(),target_id uuid not null references provisioning_target(id),state text not null,drift_count integer not null default 0,repair_plan jsonb not null default '[]'::jsonb,started_at timestamptz not null default now(),completed_at timestamptz);
create table audit_event(id bigint generated always as identity primary key,organisation_id uuid not null references organisation(id) on delete cascade,actor_id text not null,action text not null,entity_type text not null,entity_id text not null,payload jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now());
create table role_policy(organisation_id uuid not null references organisation(id) on delete cascade,role_key text not null,permissions text[] not null default '{}',updated_by text not null,updated_at timestamptz not null default now(),primary key(organisation_id,role_key));
